// Generates a 45-degree halftone disc for the proof illustration.
const cx = 200, cy = 196, R = 92, step = 6.4;
const a = Math.PI / 4, ca = Math.cos(a), sa = Math.sin(a);
let out = [];
for (let i = -30; i <= 30; i++) for (let j = -30; j <= 30; j++) {
  const u = i * step, v = j * step;
  const x = cx + u * ca - v * sa, y = cy + u * sa + v * ca;
  const d = Math.hypot(x - cx, y - cy);
  if (d > R) continue;
  // tone: dark at lower-left, light at upper-right
  let t = ((x - (cx - R)) * -0.35 + (y - (cy - R))) / (2 * R) ;
  t = Math.min(1, Math.max(0.04, t * 1.15 + 0.05));
  const r = (step / 2) * Math.sqrt(t) * 1.12;
  if (r < 0.35) continue;
  out.push(`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(2)}"/>`);
}
process.stdout.write(out.join(''));
EOF
